input.command:
cat > /tmp/check.js <<'EOF'
const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
const url = 'file://' + process.argv[2] + '/card.html';
(async () => {
  const b = await chromium.launch();
  for (const [w,h,n] of [[1080,1080,'square'],[1920,1080,'landscape'],[1080,1920,'story']]) {
    const p = await b.newPage({ viewport:{width:w,height:h} });
    await p.goto(url); await p.waitForTimeout(400);
    const r = await p.evaluate(({w,h}) => {
      const out = { over: [], circle: null };
      document.querySelectorAll('*').forEach(el => {
        const cs = getComputedStyle(el);
        if (cs.display === 'none' || cs.visibility === 'hidden') return;
        const b = el.getBoundingClientRect();
        if (b.width === 0 && b.height === 0) return;
        if (b.left < -0.5 || b.top < -0.5 || b.right > w + 0.5 || b.bottom > h + 0.5)
          out.over.push(`${el.tagName}.${el.className||''} ${JSON.stringify([b.left,b.top,b.right,b.bottom].map(v=>+v.toFixed(1)))}`);
        if (el.scrollHeight > el.clientHeight + 1 || el.scrollWidth > el.clientWidth + 1)
          out.over.push(`SCROLL ${el.tagName}.${el.className||''} ${el.scrollWidth}x${el.scrollHeight} vs ${el.clientWidth}x${el.clientHeight}`);
      });
      const ps = [...document.querySelectorAll('.portrait')].filter(e => e.offsetParent !== null)
        .map(e => { const r = e.getBoundingClientRect(); const i = e.querySelector('img').getBoundingClientRect();
          return { outer:[+r.width.toFixed(2),+r.height.toFixed(2)], img:[+i.width.toFixed(2),+i.height.toFixed(2)] }; });
      out.circle = ps;
      // overlap check between key text blocks
      const keys = ['header','.eyebrow','h1','.sname','.srole','.meta','.btn'];
      const boxes = keys.map(k => [k, document.querySelector(k)]).filter(([k,e]) => e && e.offsetParent !== null)
        .map(([k,e]) => [k, e.getBoundingClientRect()]);
      out.overlaps = [];
      for (let i=0;i<boxes.length;i++) for (let j=i+1;j<boxes.length;j++) {
        const a=boxes[i][1], c=boxes[j][1];
        const ox = Math.min(a.right,c.right)-Math.max(a.left,c.left);
        const oy = Math.min(a.bottom,c.bottom)-Math.max(a.top,c.top);
        if (ox>1 && oy>1) out.overlaps.push(`${boxes[i][0]} x ${boxes[j][0]} (${ox.toFixed(1)}x${oy.toFixed(1)})`);
      }
      out.font = document.fonts.check('700 60px Inter');
      return out;
    }, {w,h});
    console.log(n, JSON.stringify(r, null, 1));
    await p.close();
  }
  await b.close();
})();
EOF
node /tmp/check.js "$PWD"

